pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v, uint256 initialBalance, uint256 transferAmount) public {
        // Ensure arrays are non-empty and have matching lengths
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Keep initialBalance and transferAmount within reasonable bounds
        vm.assume(initialBalance <= 1_000_000 ether);
        vm.assume(transferAmount <= initialBalance);

        // Deploy an adversarial callee that will attempt to transfer C's Ether if called via delegatecall
        EtherDrainer helper = new EtherDrainer();
        caddress = address(helper);

        // Give C some Ether
        vm.deal(address(c), initialBalance);

        // Record C's balance before the call
        uint256 balanceBefore = address(c).balance;

        // Perform the transfer call
        bool success = c.transfer(from, caddress, _tos, v);

        // C's balance after the call must remain unchanged
        assertEq(address(c).balance, balanceBefore, "C's balance changed after transfer");
    }
}

contract EtherDrainer {
    // When delegatecall hits this, it runs in C's context and can transfer C's Ether
    function transferFrom(address from, address to, uint256 amount) external {
        // This will execute in C's context if called via delegatecall, draining C's balance
        payable(to).transfer(amount);
    }
}

