import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        // Bound v length to be <= _tos.length so reference does not revert from OOB;
        // this keeps the domain admissible for the reference while allowing v.length <= _tos.length.
        // The buggy version still reverts for some inputs where v.length > _tos.length,
        // but we must not restrict the domain so that such inputs are excluded from the test.
        // We must let the fuzzer find a case where v.length > _tos.length.
        // Therefore, we do NOT bound v.length relative to _tos.length. Instead, we catch reverts
        // and assert that the reference either succeeds or reverts in a way the bug does not.
        // Specifically, the reference reverts only if an external call inside the loop reverts,
        // but never from an OOB array access. The mutant reverts with OOB when v.length > _tos.length.

        bool refOk;
        // We cannot call `c.transfer` with `from` as `msg.sender`? `transfer` is `public` so `from` is just a parameter.
        // No prank needed for `from`; the function just forwards calls. However, the external `transferFrom` calls
        // may fail if `caddress` doesn't have code or reverts, but the reference does not revert from OOB.
        // We'll use try/catch.
        try c.transfer(from, caddress, _tos, v) returns (bool success) {
            refOk = success;
        } catch {
            refOk = false;
        }

        // Now we need to assert something that holds for the reference but not the mutant.
        // Since we cannot observe internal state (no state variables are public), we must rely on revert behavior.
        // The mutant reverts with OOB (panic code 0x32) if v.length > _tos.length, while the reference does not.
        // However, try/catch does not distinguish panic from other reverts. But we can assert that if v.length <= _tos.length,
        // both should behave identically (no OOB). The bug is only triggered when v.length > _tos.length.
        // So the rule: "If v.length > _tos.length, the call MUST revert" is not true for reference.
        // The reference succeeds or reverts depending on external calls, not due to OOB.
        // So the general property: "The call does NOT revert due to an out-of-bounds array access."
        // Unfortunately, we cannot directly assert "no panic" because panic is caught by catch too.
        // But we can craft a scenario where the external calls succeed, so the reference succeeds,
        // and then if v.length > _tos.length, the mutant reverts (panic). In that case, refOk = true, bugOk = false.
        // But we don't have the buggy version here. We only test the reference.
        // The requirement is: test PASSES on reference for ALL inputs, FAILS on buggy for SOME input.
        // So we need an assertion that is true for reference but false for buggy.
        // We can assert: "If v.length > _tos.length, the call does NOT revert due to OOB"? Not expressible.
        // Instead, we can use the fact that reference never accesses _tos beyond its length.
        // We can deploy a helper that always reverts on transferFrom, but that would make reference revert even without OOB.
        // Not helpful.
        // Better: deploy a helper that NEVER reverts (empty fallback or a mock that returns true). Then the reference is guaranteed to succeed if all external calls succeed (it doesn't check return values). Wait, `caddress.call(abi.encodeWithSelector(id,from,_tos[i],v[i]))` - it ignores the return value and bool success. It doesn't matter if it succeeds or fails; the call itself can revert if the contract doesn't exist or runs out of gas, but if the target is a contract that exists and does not revert, the call succeeds. The reference does not check the return value, so it returns `true` at the end regardless.
        // So if we ensure the external call never reverts, reference always returns true.
        // We can deploy a simple contract that has a `transferFrom` function that does nothing (no revert).
        // Then reference succeeds (returns true) for any lengths. The mutant with v.length > _tos.length will revert with OOB (bad array access).
        // That gives a clear difference: reference succeeds, mutant reverts.
        // The assertion: "The call succeeds and returns true." That holds for reference, fails for mutant when v.length > _tos.length.
        // But we must not hardcode the adversarial behavior; we let the fuzzer explore v.length vs _tos.length.
        // The helper is needed because a fuzzed `caddress` is an EOA with no code, and a low-level call to an EOA always succeeds (returns true, no revert). Wait, a low-level call to an EOA returns success, and no code is executed, so it works! Actually, low-level `call` to an EOA with some calldata: does it revert? No, it returns true and no code runs. So the `transferFrom` selector call to an EOA will also succeed (no revert) because the call itself doesn't revert, it just returns false? No, `address.call()` returns (bool success, bytes memory data). If the address has no code, the call returns `true`. So it's fine. The call will not revert. So we don't need a helper contract at all! The fuzzed `caddress` can be any address, including EOAs, and the external calls will succeed silently. Therefore, reference will not revert due to external calls. Then reference returns true for all inputs (since `require(_tos.length > 0)` passes, loop runs, calls succeed). The mutant will revert with array out-of-bounds if `v.length > _tos.length` because it tries to access `_tos[i]` for i beyond _tos.length-1. That will cause a panic revert. So we can simply assert that `refOk` is true. That will pass for reference, fail for mutant when the fuzzer picks v.length > _tos.length.

        assertTrue(refOk);
    }
}

