pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint256 len, uint256 extra) public {
        // Restrict lengths to a reasonable range to avoid huge-loop gas issues, but keep it wide.
        uint256 boundLen = bound(len, 1, 5);
        uint256 boundExtra = bound(extra, 0, 3);
        // Build two arrays of equal length, keeping the fuzz freedom in values.
        // We fuzz the actual address values inside the arrays randomly.
        // For pure differential detection, we make _tos and v the same length;
        // the reference always succeeds with _tos.length calls, the mutant either
        // loops correctly when v.length == _tos.length, or misbehaves only when lengths differ.
        // To detect the bug generically without restricting to v.length > _tos.length,
        // we observe that the reference never reverts due to array access via call return,
        // while the mutant reverts with panic if v.length > _tos.length.
        // Equally-length case is safe for the reference; the mutant also safe there.
        // So the rule is: for any _tos.length >= 1, and v.length == _tos.length,
        // the call does NOT revert due to an out-of-bounds panic.
        // We fuzz _tos elements and v elements randomly.
        uint256 l = boundLen;
        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        // Fill with fuzzer-friendly pseudorandom addresses and amounts.
        // We can use the caller address and block.timestamp as a seed to keep it deterministic within a fuzz run,
        // but forge will vary the inputs. We just loop with fuzzed length.
        for (uint i = 0; i < l; i++) {
            // Derive deterministic but varying addresses from i and from/to avoid vm.assume rejection
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, caddress, i, block.timestamp)))));
            vals[i] = bound(i, 0, type(uint128).max);
        }
        bool success;
        try c.transfer(from, caddress, tos, vals) {
            success = true;
        } catch {
            success = false;
        }
        // The reference contract, given _tos.length > 0 and v.length == _tos.length,
        // only issues transferFrom calls that may revert for other reasons (e.g., token not being a contract),
        // but never panics from array bounds. The mutant behaves identically when lengths are equal,
        // so the test must detect the difference when they are not equal. To universally target the bug,
        // we need a rule that fails for M. The most direct rule: the call does not revert with a reason that
        // indicates an array-out-of-bounds panic. Since we cannot inspect revert reason in forge, we use
        // a helper that ALWAYS succeeds on call to eliminate non-panic reverts.
        // The approach already tried is about out-of-bounds access, so we need to ensure the external call
        // succeeds, making the only revert source be the array access on the mutant when v is shorter or longer.
        // We deploy a helper that returns true for the transferFrom selector.
    }
}

